contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // one public function containing the property-based test
    // params: tokenIds array, baseTokenAmount to deposit (amount of ETH if pool uses native token), and a flag indicating whether we attempt to send ETH
    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount, bool sendEth) public payable {
        // Ensure this contract holds enough ETH if we plan to send
        if (sendEth) {
            require(address(this).balance >= baseTokenAmount, "Insufficient test ETH");
        }

        // Observe pre-state: c's balance and public baseToken
        uint256 beforeBalance = address(c).balance;
        address poolBaseToken = c.baseToken(); // public getter

        bool reverted;
        // Make the deposit call as the test caller (this contract). Must be top-level.
        if (sendEth) {
            // If we are sending ETH, call payable variant
            try c.deposit{value: baseTokenAmount}(tokenIds, baseTokenAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // no ETH sent
            try c.deposit(tokenIds, baseTokenAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBalance = address(c).balance;

        // General rule (single assert):
        // - If pool uses native token (baseToken == address(0)) then the deposit call must either revert, or if it succeeded then the pool's ETH balance increased by exactly baseTokenAmount (and this contract's ETH decreased accordingly).
        // - If pool uses ERC20 (baseToken != address(0)) then the pool's ETH balance must be unchanged when the call succeeds.
        // The assert encodes that property using only observed values and revert flag.
        assert(
            (
                poolBaseToken == address(0) ?
                    (
                        reverted || afterBalance == beforeBalance + baseTokenAmount
                    )
                :
                    (
                        // ERC20 pool: either reverted or ETH balance unchanged
                        reverted || afterBalance == beforeBalance
                    )
            )
        );
    }

    // receive to accept ETH when the checker funds this contract
    receive() external payable {}
}

