contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test that deposit transfers the provided NFTs into the pool and, for native baseToken==address(0),
    // that address(c).balance increases by baseTokenAmount when deposit is called with ETH.
    // Parameters:
    // - tokenIds: array of token ids to deposit
    // - baseTokenAmount: amount of base token (ETH if pool uses native) to send with the call
    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount) public payable {
        // Ensure this contract has enough ETH to forward if needed
        if (address(this).balance < baseTokenAmount) return;

        // Observe before-values via public getters
        address nftAddr = c.nft();
        // If nft address is zero, deposit will likely revert; require a sensible precondition to let test run
        require(nftAddr != address(0));

        uint256 beforeNftBalance = ERC721(nftAddr).balanceOf(address(c));
        uint256 beforePoolBalance = address(c).balance;

        bool reverted;
        // Call deposit on c; must be a top-level state-changing call.
        try c.deposit{value: baseTokenAmount}(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call observations
        uint256 afterNftBalance = ERC721(nftAddr).balanceOf(address(c));
        uint256 afterPoolBalance = address(c).balance;

        // General rule (one assert): If deposit did NOT revert then
        // 1) the pool's NFT balance increased by at least the number of tokenIds deposited, and
        // 2) if the pool uses native ETH as baseToken (observed as flashFeeToken() == address(0) OR baseToken() == address(0)),
        //    then the pool's ETH balance increased by at least baseTokenAmount (caller forwarded that amount).
        // We use c.baseToken() public getter to determine token type. This is a general invariant about deposit effects.
        assert(
            reverted || (
                afterNftBalance >= beforeNftBalance + tokenIds.length
                && ( (c.baseToken() != address(0)) || (afterPoolBalance >= beforePoolBalance + baseTokenAmount) )
            )
        );
    }

    receive() external payable {}
}

