contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public test function: attempt to call buy and assert on reserve changes vs returned quote
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 ethValue) public payable {
        // Build MerkleMultiProof calldata struct for sumWeightsAndValidateProof
        // We will use the pool's public read functions to observe before/after

        // Preconditions for sending ETH to c.buy: if pool.baseToken() == address(0) then we may send ETH; otherwise we must not send ETH
        address baseToken = c.baseToken();
        if (baseToken == address(0)) {
            require(address(this).balance >= ethValue, "no ETH");
        } else {
            // when baseToken != 0 we must not send ETH
            require(ethValue == 0, "must not send ETH when base token is ERC20");
        }

        // Read before-values
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();

        // Prepare MerkleMultiProof struct in memory for call
        C.MerkleMultiProof memory mproof;
        mproof.proof = proof;
        mproof.flags = flags;

        // Call buy and capture revert or returned amounts
        bool reverted = false;
        uint256 netInputAmount = 0;
        uint256 feeAmount = 0;
        uint256 protocolFeeAmount = 0;

        try c.buy{value: ethValue}(tokenIds, tokenWeights, mproof) returns (uint256 _net, uint256 _fee, uint256 _protocol) {
            netInputAmount = _net;
            feeAmount = _fee;
            protocolFeeAmount = _protocol;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();

        // Compute sum of weights (in uint256 to avoid overflow) — this mirrors sumWeightsAndValidateProof logic
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // General invariant we assert:
        // If buy reverted then reserves must be unchanged (call had no effect). If buy succeeded then
        // afterVirtualNft == beforeVirtualNft - sumWeights (no underflow) and afterVirtualBase >= beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount)
        // We express "no underflow" by checking beforeVirtualNft >= sumWeights and using uint128 comparisons.

        assert(
            (reverted && afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft)
            || (
                !reverted
                && beforeVirtualNft >= uint128(sumWeights)
                && afterVirtualNft == uint128(uint256(beforeVirtualNft) - sumWeights)
                && afterVirtualBase >= uint128(uint256(beforeVirtualBase) + (netInputAmount - feeAmount - protocolFeeAmount))
            )
        );
    }

    receive() external payable {}
}

