    // single public test: try buy with bounded-size arrays; assert reserves unchanged on revert or nft reserve decreased by sumWeights on success
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 ethValue) public payable {
        // keep arrays small to help verification
        require(tokenIds.length == tokenWeights.length && tokenIds.length <= 4, "bad lengths");
        require(proof.length <= 8 && flags.length <= 8, "proof too large");

        // respect ETH sending rule: if pool has ERC20 base token, we must not send ETH
        address baseToken = c.baseToken();
        if (baseToken == address(0)) {
            require(address(this).balance >= ethValue, "insufficient balance for ETH");
        } else {
            require(ethValue == 0, "must not send ETH when ERC20 base token");
        }

        // observe before
        uint128 beforeNft = c.virtualNftReserves();

        // build MerkleMultiProof struct
        C.MerkleMultiProof memory mproof;
        mproof.proof = proof;
        mproof.flags = flags;

        // call buy and capture revert
        bool reverted = false;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: ethValue}(tokenIds, tokenWeights, mproof) returns (uint256 _net, uint256 _fee, uint256 _protocol) {
            netInputAmount = _net;
            feeAmount = _fee;
            protocolFeeAmount = _protocol;
        } catch {
            reverted = true;
        }

        // observe after
        uint128 afterNft = c.virtualNftReserves();

        // compute sumWeights (uint256) to avoid overflow in accumulation
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // General rule: if buy reverted then virtualNftReserves unchanged; otherwise it decreased by exactly sumWeights (no underflow allowed)
        assert(
            (reverted && afterNft == beforeNft)
            || (
                !reverted
                && beforeNft >= uint128(sumWeights)
                && afterNft == uint128(uint256(beforeNft) - sumWeights)
            )
        );
    }

    receive() external payable {}
}

